{
  "pass": false,
  "problems": [
    {
      "type": "ふりがなの読み",
      "where": "summary の es",
      "detail": "「職員《しょくいん》の数《すう》」となっています。「〜の数」は「かず」と読みます（blocks/3/textのesでも「数《かず》」となっています）。",
      "fix": "「職員《しょくいん》の数《かず》」に直す。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/0/text の hs",
      "detail": "stdにある「振替休日」が抜けており、また「何に基づいて決まっているのか（根拠）」という問いが「だれが、どうやって決めているのでしょう？」に変わっています。",
      "fix": "「カレンダーの祝日や振替休日は、何をもとに決められているのでしょう？」などに直す。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/1/text の hs",
      "detail": "stdにある「外局を通じて競争政策・治安・個人情報・金融・消費者・こども政策も担う」という内容が丸ごと抜けています。",
      "fix": "公正取引委員会や警察庁、こども家庭庁などの外局を通じて、治安や金融、消費者、こどもの政策なども担当している内容を追加する。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/3/text の hs",
      "detail": "stdにある「特別会計は含まない」という情報が抜け落ちています（補正予算しか触れられていません）。",
      "fix": "「特別会計や、あとから追加した補正予算は入っていません」など、特別会計が含まれない旨を追加する。"
    }
  ]
}
